def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    markers = {(r, c) for r in range(h) for c in range(w)
               if grid[r][c] != background}
    out = [row[:] for row in grid]

    for r in range(h):
        cols = [c for rr, c in markers if rr == r]
        if len(cols) >= 2:
            for c in range(min(cols) + 1, max(cols)):
                if grid[r][c] == background:
                    out[r][c] = 3

    for c in range(w):
        rows = [r for r, cc in markers if cc == c]
        if len(rows) >= 2:
            for r in range(min(rows) + 1, max(rows)):
                if grid[r][c] == background:
                    out[r][c] = 3

    return out
